//! 📽️ Original presentation shape fields and shared document blocks remain in one caller workspace.
use super::*;
use semio_framework_os_kernel::sqlite_snapshot::{transfer,artifact::{RowIndexStorage,reconstruct_text_into,reconstruct_blob_into}};
use crate::standards::v1::subsets::base::io::sqlite::snapshot::native_decoding::workspace;
use crate::standards::v1::subsets::document::{schema::snapshot::DocBlock,io::sqlite::snapshot::{BlockReconstructionStorage,reconstruct_block_collections_into}};

/// 🫙️ Retains the actual snapshot and every relationship, name, root and block frontier.
#[derive(semio_framework_value::RetireOwned)]
struct Prefix{snapshot:Option<SemioPresentationSnapshot>,validation:transfer::SchemaValidationStorage,indices:[RowIndexStorage;10],master_order:Vec<usize>,layout_order:Vec<usize>,slide_order:Vec<usize>,master_names:Vec<usize>,layout_names:Vec<usize>,slide_names:Vec<usize>,shape_order:Vec<usize>,row_order:Vec<usize>,cell_order:Vec<usize>,roots:Vec<i64>,root_order:Vec<usize>,root_used:Vec<u8>,blocks:BlockReconstructionStorage}
impl Prefix{fn empty()->Self{Self{snapshot:Some(SemioPresentationSnapshot{schema:String::new(),masters:Vec::new(),layouts:Vec::new(),slides:Vec::new()}),validation:transfer::SchemaValidationStorage::empty(),indices:std::array::from_fn(|_|RowIndexStorage::empty()),master_order:Vec::new(),layout_order:Vec::new(),slide_order:Vec::new(),master_names:Vec::new(),layout_names:Vec::new(),slide_names:Vec::new(),shape_order:Vec::new(),row_order:Vec::new(),cell_order:Vec::new(),roots:Vec::new(),root_order:Vec::new(),root_used:Vec::new(),blocks:BlockReconstructionStorage::empty()}}}
/// 📏️ Checks root extent before its original backing is admitted.
fn extent(left:usize,right:usize)->Result<usize,ValueError>{left.checked_add(right).ok_or_else(||ValueError::literal(ValueRefusalKind::OwnershipLimit,"presentation root extent overflow"))}
/// 🛂️ Binds one source family to original scalar row storage.
fn details<'a>(storage:&'a mut RowIndexStorage,db:&'a SqliteDatabase,name:&str,columns:usize,control:&mut SqliteSnapshotControl<'_>)->Result<RowIndex<'a>,ValueError>{RowIndex::new(storage,db,name,columns,float_columns(name),control,"invalid presentation row identity or columns")}
/// 🪪️ Validates full literal identity keys in original scratch and requires the actual document owner.
fn names(rows:&RowIndex<'_>,scratch:&mut Vec<usize>,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{rows.unique_text(scratch,rows.indices(),3,control,"invalid presentation native identity or owner")?;for &index in rows.indices(){if rows.row(index)?.integer(1)?!=1{return Err(presentation_invalid("invalid presentation native identity or owner"))}control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,index,rows.len())?;}Ok(())}
/// 👪️ Checks each actual foreign owner before sorting original scalar positions.
fn group_into(order:&mut Vec<usize>,rows:&RowIndex<'_>,parents:&RowIndex<'_>,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{for &index in rows.indices(){if parents.get(rows.row(index)?.integer(1)?,control)?.is_none(){return Err(presentation_invalid("dangling presentation relationship owner"))}}rows.grouped_by_into(order,2,control,"presentation order must be contiguous",|row|Ok((0,Some(row.integer(1)?))))}
/// 🪟️ Borrows the original indices and completed block output without owning a replacement container.
struct Content<'a>{shapes:RowIndex<'a>,shape_order:&'a[usize],text_boxes:RowIndex<'a>,pictures:RowIndex<'a>,tables:RowIndex<'a>,placeholders:RowIndex<'a>,rows:RowIndex<'a>,row_order:&'a[usize],cells:RowIndex<'a>,cell_order:&'a[usize],roots:&'a[i64],root_order:&'a[usize],root_used:&'a mut[u8],blocks:&'a mut[Vec<DocBlock>]}
impl Content<'_>{
 /// 🫴️ Transfers an actual original root after the final fallible lookup and consumed marker.
 fn take_blocks(&mut self,id:i64,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<DocBlock>,ValueError>{
  let(mut low,mut high)=(0,self.root_order.len());while low<high{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,low,self.root_order.len())?;let middle=low+(high-low)/2;let index=self.root_order[middle];match self.roots[index].cmp(&id){std::cmp::Ordering::Less=>low=middle+1,std::cmp::Ordering::Greater=>high=middle,std::cmp::Ordering::Equal=>{if self.root_used[index]!=0{return Err(presentation_invalid("missing presentation block collection"))}self.root_used[index]=1;return Ok(std::mem::take(&mut self.blocks[index]))}}}Err(presentation_invalid("missing presentation block collection"))
 }
 /// 🖼️ Initializes original shape and nested row slots before copying any picture or placeholder field.
 fn shapes_into(&mut self,output:&mut Vec<SlideShape>,owner:(u8,Option<i64>),control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{
  let range=self.shapes.range_by(self.shape_order,owner,control,presentation_owner)?;*output=transfer::reserve(range.len(),control)?;
  for ordinal in range{
   let row=self.shapes.take_index(self.shape_order[ordinal],control)?.ok_or_else(||presentation_invalid("duplicate presentation shape ownership"))?;let id=row.rowid;let frame=SlideFrame{origin:SemioPoint2{x:row.real(6)?,y:row.real(7)?},width:row.real(8)?,height:row.real(9)?};
   match row.text(5)?{
    "textBox"=>{let detail=self.text_boxes.take(id,control)?.ok_or_else(||presentation_invalid("missing presentation text box fields"))?;output.push(SlideShape::TextBox{frame,blocks:Vec::new()});if let SlideShape::TextBox{blocks,..}=output.last_mut().unwrap(){*blocks=self.take_blocks(detail.integer(1)?,control)?;}},
    "picture"=>{let detail=self.pictures.take(id,control)?.ok_or_else(||presentation_invalid("missing presentation picture fields"))?;output.push(SlideShape::Picture{frame,image:SlidePictureImage::default()});if let SlideShape::Picture{image,..}=output.last_mut().unwrap(){reconstruct_text_into(&mut image.asset_id,control,detail.text(1)?)?;reconstruct_text_into(&mut image.mime,control,detail.text(2)?)?;reconstruct_blob_into(&mut image.bytes,control,detail.blob(3)?)?;}},
    "table"=>{self.tables.take(id,control)?.ok_or_else(||presentation_invalid("missing presentation table fields"))?;output.push(SlideShape::Table{frame,rows:Vec::new()});let range=self.rows.range_by(self.row_order,(0,Some(id)),control,|row|Ok((0,Some(row.integer(1)?))))?;
     if let SlideShape::Table{rows,..}=output.last_mut().unwrap(){*rows=transfer::reserve(range.len(),control)?;for ordinal in range{let row=self.rows.take_index(self.row_order[ordinal],control)?.ok_or_else(||presentation_invalid("duplicate presentation table row"))?;let range=self.cells.range_by(self.cell_order,(0,Some(row.rowid)),control,|row|Ok((0,Some(row.integer(1)?))))?;rows.push(SlideTableRow::default());let native_row=rows.last_mut().unwrap();native_row.cells=transfer::reserve(range.len(),control)?;for ordinal in range{let cell=self.cells.take_index(self.cell_order[ordinal],control)?.ok_or_else(||presentation_invalid("duplicate presentation table cell"))?;native_row.cells.push(SlideTableCell{blocks:self.take_blocks(cell.integer(3)?,control)?});}}}
    },
    "placeholder"=>{let detail=self.placeholders.take(id,control)?.ok_or_else(||presentation_invalid("missing presentation placeholder fields"))?;let other=detail.optional_text(2)?;let kind=match(detail.text(1)?,other){("title",None)=>PlaceholderKind::Title,("subtitle",None)=>PlaceholderKind::Subtitle,("body",None)=>PlaceholderKind::Body,("footer",None)=>PlaceholderKind::Footer,("slideNumber",None)=>PlaceholderKind::SlideNumber,("dateTime",None)=>PlaceholderKind::DateTime,("other",Some(_))=>PlaceholderKind::Other{value:String::new()},_=>return Err(presentation_invalid("invalid presentation placeholder shape"))};output.push(SlideShape::Placeholder{frame,kind});if let SlideShape::Placeholder{kind:PlaceholderKind::Other{value},..}=output.last_mut().unwrap(){reconstruct_text_into(value,control,other.unwrap())?;}},
    _=>return Err(presentation_invalid("unknown presentation shape kind"))
   }
   control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,output.len(),self.shapes.len())?;
  }Ok(())
 }
}
/// 🏛️ Reserves the actual outer presentation workspace before any schema or field materialization.
pub(super)fn reconstruct(db:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>,schema:&str)->Result<SemioPresentationSnapshot,ValueError>{workspace::reconstruct_projected(control,Prefix::empty,|prefix,control|reconstruct_into(prefix,db,control,schema),|prefix|prefix.snapshot.take().expect("complete Presentation snapshot"))}
fn reconstruct_into(prefix:&mut Prefix,db:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>,schema:&str)->Result<(),ValueError>{
 control.check_database(db,SqliteSnapshotPhase::ReconstructSnapshot)?;transfer::validate_database_into(&mut prefix.validation,db,schema,SqliteSnapshotPhase::ReconstructSnapshot,control)?;transfer::validate_component_into(&mut prefix.validation,db,<SemioPresentationSnapshot as ArtifactSqliteSnapshot>::SQLITE_SCHEMA,SqliteSnapshotPhase::ReconstructSnapshot,control)?;
 let Prefix{snapshot,validation:_,indices,master_order,layout_order,slide_order,master_names,layout_names,slide_names,shape_order,row_order,cell_order,roots,root_order,root_used,blocks}=prefix;
 let [master_storage,layout_storage,slide_storage,shape_storage,text_storage,picture_storage,table_storage,placeholder_storage,row_storage,cell_storage]=indices;
 let snapshot=snapshot.as_mut().unwrap();let doc=single_float_row(db,"semio_presentation_document")?;identity(doc,2)?;if doc.rowid!=1{return Err(presentation_invalid("invalid presentation document identity"))}
 let masters=details(master_storage,db,"semio_presentation_master",4,control)?;let layouts=details(layout_storage,db,"semio_presentation_layout",5,control)?;let slides=details(slide_storage,db,"semio_presentation_slide",6,control)?;
 names(&masters,master_names,control)?;names(&layouts,layout_names,control)?;names(&slides,slide_names,control)?;
 masters.ordered_into(master_order,2,control,"presentation order must be contiguous")?;layouts.ordered_into(layout_order,2,control,"presentation order must be contiguous")?;slides.ordered_into(slide_order,2,control,"presentation order must be contiguous")?;
 let shapes=details(shape_storage,db,"semio_presentation_shape",10,control)?;for &index in shapes.indices(){let owner=presentation_owner(shapes.row(index)?)?;let rows=match owner.0{0=>&masters,1=>&layouts,_=>&slides};if rows.get(owner.1.ok_or_else(||presentation_invalid("missing presentation shape owner"))?,control)?.is_none(){return Err(presentation_invalid("presentation shape requires one declared owner"))}}
 shapes.grouped_by_into(shape_order,4,control,"presentation order must be contiguous",presentation_owner)?;
 let text_boxes=details(text_storage,db,"semio_presentation_text_box",2,control)?;let pictures=details(picture_storage,db,"semio_presentation_picture",4,control)?;let tables=details(table_storage,db,"semio_presentation_shape_table",1,control)?;let placeholders=details(placeholder_storage,db,"semio_presentation_placeholder",3,control)?;let rows=details(row_storage,db,"semio_presentation_shape_table_row",3,control)?;let cells=details(cell_storage,db,"semio_presentation_shape_table_cell",4,control)?;
 group_into(row_order,&rows,&tables,control)?;group_into(cell_order,&cells,&rows,control)?;
 let total=extent(extent(text_boxes.len(),cells.len())?,slides.len())?;*roots=transfer::reserve(total,control)?;*root_order=transfer::reserve(total,control)?;*root_used=transfer::reserve(total,control)?;
 for &index in text_boxes.indices(){roots.push(text_boxes.row(index)?.integer(1)?);control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,roots.len(),total)?;}for &index in cells.indices(){roots.push(cells.row(index)?.integer(3)?);control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,roots.len(),total)?;}for &index in slide_order.iter(){roots.push(slides.row(index)?.integer(5)?);control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,roots.len(),total)?;}
 for index in 0..total{root_order.push(index);root_used.push(0);control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,index,total)?;}
 transfer::heap_sort(root_order,SqliteSnapshotPhase::ReconstructSnapshot,control,|left,right,_|Ok(roots[*left].cmp(&roots[*right])))?;
 for pair in root_order.windows(2){if roots[pair[0]]==roots[pair[1]]{return Err(presentation_invalid("multiply owned presentation block root"))}control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,pair[0],total)?;}
 reconstruct_block_collections_into(blocks,db,BLOCKS,roots,None,None,control)?;
 let mut content=Content{shapes,shape_order,text_boxes,pictures,tables,placeholders,rows,row_order,cells,cell_order,roots,root_order,root_used,blocks:&mut blocks.output};
 snapshot.masters=transfer::reserve(master_order.len(),control)?;for &index in master_order.iter(){let row=masters.row(index)?;snapshot.masters.push(SlideMaster::default());let master=snapshot.masters.last_mut().unwrap();reconstruct_text_into(&mut master.id,control,row.text(3)?)?;content.shapes_into(&mut master.shapes,(0,Some(row.rowid)),control)?;}
 snapshot.layouts=transfer::reserve(layout_order.len(),control)?;for &index in layout_order.iter(){let row=layouts.row(index)?;snapshot.layouts.push(SlideLayout::default());let layout=snapshot.layouts.last_mut().unwrap();reconstruct_text_into(&mut layout.id,control,row.text(3)?)?;let master=masters.get(row.integer(4)?,control)?.ok_or_else(||presentation_invalid("dangling presentation layout master"))?;reconstruct_text_into(&mut layout.master_id,control,master.text(3)?)?;content.shapes_into(&mut layout.shapes,(1,Some(row.rowid)),control)?;}
 snapshot.slides=transfer::reserve(slide_order.len(),control)?;for &index in slide_order.iter(){let row=slides.row(index)?;snapshot.slides.push(Slide::default());let slide=snapshot.slides.last_mut().unwrap();reconstruct_text_into(&mut slide.id,control,row.text(3)?)?;if let Some(id)=optional_integer(row,4)?{let layout=layouts.get(id,control)?.ok_or_else(||presentation_invalid("dangling presentation slide layout"))?;slide.layout_id=Some(String::new());reconstruct_text_into(slide.layout_id.as_mut().unwrap(),control,layout.text(3)?)?;}content.shapes_into(&mut slide.shapes,(2,Some(row.rowid)),control)?;slide.notes=content.take_blocks(row.integer(5)?,control)?;}
 if [content.shapes.remaining(),content.text_boxes.remaining(),content.pictures.remaining(),content.tables.remaining(),content.placeholders.remaining(),content.rows.remaining(),content.cells.remaining()].iter().any(|count|*count!=0){return Err(presentation_invalid("orphan or contradictory presentation shape detail"))}
 for(index,used)in content.root_used.iter().enumerate(){control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,index,content.root_used.len())?;if *used==0{return Err(presentation_invalid("orphan presentation content"))}}
 reconstruct_text_into(&mut snapshot.schema,control,doc.text(1)?)?;control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,1,1)
}
